{
  "id": "V001",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "화물 청구서 검토 시간을 줄이려는 목적이 BUSINESS에 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "항목별 청구 금액을 합의 요율과 비교하고 검토 목록에 남기는 행동이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "화물 청구서 항목과 합의된 요율이 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "화물 청구서 항목별 금액과 합의된 요율이 비교 입력으로 보존됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "의심되는 과다 청구 부분과 비교 근거를 검토 목록에 남기는 결과가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "자동 수정·지급을 하지 않고 담당자가 확인한 뒤 처리한다는 제약이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "운송비 검토 담당자의 역할과 담당자 확인 후 처리하는 운영 방식이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "자동 수정이나 지급은 하지 않으며 담당자 확인 후 처리한다는 뜻이다. 담당자가 매번 특정 후속 조치를 모두 수행한다고 단정하지 않는다."
}
